def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((v for v in range(1, 10)
                if any(all(x == v for x in row) for row in grid)), None)
    if sep is None:
        return [row[:] for row in grid]

    rs = [r for r in range(h) if all(x == sep for x in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rb, cb = [-1] + rs + [h], [-1] + cs + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    out = [row[:] for row in grid]

    def cells(i, j):
        r0, r1 = rows[i]
        c0, c1 = cols[j]
        return [(r, c) for r in range(r0, r1) for c in range(c0, c1)]

    def occupied(i, j):
        return any(grid[r][c] not in (0, sep) for r, c in cells(i, j))

    # Copy a tile's motif, reflected at the shared divider, into a blank
    # neighboring tile when the same motif is represented elsewhere on that
    # tile row or column.
    for i in range(len(rows)):
        for j in range(len(cols)):
            if not occupied(i, j):
                continue
            for di, dj in ((1, 0), (0, 1)):
                ni, nj = i + di, j + dj
                if ni >= len(rows) or nj >= len(cols) or occupied(ni, nj):
                    continue
                r0, r1 = rows[i]
                c0, c1 = cols[j]
                nr0, nr1 = rows[ni]
                nc0, nc1 = cols[nj]
                if r1-r0 != nr1-nr0 or c1-c0 != nc1-nc0:
                    continue
                # Find a matching motif in another tile along this band.
                found = False
                for pi, pj in ([(i, k) for k in range(len(cols)) if k != j]
                               if di else
                               [(k, j) for k in range(len(rows)) if k != i]):
                    if occupied(pi, pj):
                        found = True
                        break
                if not found:
                    continue
                for r in range(r1-r0):
                    for c in range(c1-c0):
                        v = grid[r0+r][c0+c]
                        if v not in (0, sep):
                            rr = nr0 + (r1-r0-1-r if di else r)
                            cc = nc0 + (c1-c0-1-c if dj else c)
                            out[rr][cc] = v
    return out
